"""The SAPN SUMMARY CSV reader (P2 spec §4.2, §13.1). Every file is generated by `make_sources`."""

import dataclasses
from datetime import date
from decimal import Decimal

import pytest

from energatron.core.errors import InvalidInputError
from energatron.core.sapn_summary import SummaryRead, SummaryRow, SummaryScan, read_summary_csv, scan_summary_csv
from tests.fixtures.make_sources import SummaryRow as FixtureRow
from tests.fixtures.make_sources import make_sapn_summary_csv
from tests.fixtures.synthetic import SYNTHETIC_NMI11, SYNTHETIC_SERIAL

ROWS = (
    FixtureRow(date(2025, 1, 1), date(2025, 1, 31), numbers=("123.456", "2.000", "3.000", "0.500")),
    FixtureRow(date(2025, 2, 1), date(2025, 2, 28), quality="AF", numbers=("99.000", "2.000", "3.000", "0.500")),
)


def csv(rows: tuple[FixtureRow, ...] = ROWS) -> bytes:
    return make_sapn_summary_csv(rows)


def edit(data: bytes, old: str, new: str) -> bytes:
    text = data.decode("utf-8")
    assert old in text
    return text.replace(old, new, 1).encode("utf-8")


def outcome(function: object, data: bytes) -> str:
    assert callable(function)
    try:
        function(data)
    except InvalidInputError as error:
        assert error.details["source"] == "sapn_summary"
        return f"rejected:{error.details['reason']}"
    return "accepted"


def test_read_returns_the_rows_in_file_order_with_field_4_and_field_7() -> None:
    read = read_summary_csv(csv())
    assert read.rows == (
        SummaryRow(start=date(2025, 1, 1), end=date(2025, 1, 31), quality="A", kwh=Decimal("123.456")),
        SummaryRow(start=date(2025, 2, 1), end=date(2025, 2, 28), quality="AF", kwh=Decimal("99.000")),
    )


def test_rows_stay_in_file_order_whatever_their_dates() -> None:
    read = read_summary_csv(csv(tuple(reversed(ROWS))))
    assert [row.start for row in read.rows] == [date(2025, 2, 1), date(2025, 1, 1)]


def test_the_value_is_a_decimal_kept_as_written() -> None:
    row = read_summary_csv(
        csv((FixtureRow(date(2025, 1, 1), date(2025, 1, 1), numbers=("1.", "2", ".5", "+3")),))
    ).rows[0]
    assert row.kwh == Decimal("1.") and isinstance(row.kwh, Decimal)


def test_scan_returns_the_same_rows_plus_the_identifiers() -> None:
    scan = scan_summary_csv(csv())
    assert scan.rows == read_summary_csv(csv()).rows
    assert scan.nmis == (SYNTHETIC_NMI11,)
    assert scan.serials == (SYNTHETIC_SERIAL,)


def test_the_identifiers_are_distinct_values_in_first_seen_order() -> None:
    other = make_sapn_summary_csv((ROWS[0],), nmi11="ZZTEST0002X", serial="SYN0000009")
    scan = scan_summary_csv(other + csv())
    assert scan.nmis == ("ZZTEST0002X", SYNTHETIC_NMI11)
    assert scan.serials == ("SYN0000009", SYNTHETIC_SERIAL)


def test_read_result_types_have_no_identifier_field() -> None:
    for model in (SummaryRead, SummaryRow):
        names = {field.name for field in dataclasses.fields(model)}
        assert not {name for name in names if any(word in name for word in ("nmi", "serial", "account", "ident"))}
    assert {field.name for field in dataclasses.fields(SummaryScan)} == {"rows", "nmis", "serials"}
    assert {field.name for field in dataclasses.fields(SummaryRead)} == {"rows"}


def test_fields_8_to_10_are_validated_but_not_returned() -> None:
    assert {field.name for field in dataclasses.fields(SummaryRow)} == {"start", "end", "quality", "kwh"}
    assert outcome(read_summary_csv, edit(csv(), ",2.000,", ",two,")) == "rejected:bad_number"


def test_crlf_lf_and_a_bom_are_accepted() -> None:
    expected = read_summary_csv(csv()).rows
    assert read_summary_csv(csv().replace(b"\r\n", b"\n")).rows == expected
    assert read_summary_csv(b"\xef\xbb\xbf" + csv()).rows == expected
    assert read_summary_csv(b"\r\n" + csv() + b"\r\n\r\n").rows == expected


CASES: dict[str, tuple[bytes, str]] = {
    "valid": (csv(), "accepted"),
    "extra_field": (edit(csv(), ",kW\r", ",kW,x\r"), "rejected:bad_field_count"),
    "bad_unit": (edit(csv(), ",kWh,", ",MWh,"), "rejected:bad_row"),
    "bad_power_unit": (edit(csv(), ",kW\r", ",MW\r"), "rejected:bad_row"),
    "bad_date": (edit(csv(), "31/01/2025", "31/13/2025"), "rejected:bad_date"),
    "iso_date": (edit(csv(), "31/01/2025", "2025-01-31"), "rejected:bad_date"),
    "range_reversed": (edit(csv(), "31/01/2025", "31/12/2024"), "rejected:bad_date_range"),
    "text_number": (edit(csv(), ",123.456,", ",one,"), "rejected:bad_number"),
    "empty_number": (edit(csv(), ",0.500,", ",,"), "rejected:bad_number"),
    "no_rows": (b"\r\n\r\n", "rejected:no_data"),
    "empty": (b"", "rejected:no_data"),
    "not_utf8": (csv() + b"\xff\r\n", "rejected:not_utf8"),
}


@pytest.mark.parametrize("name", list(CASES))
def test_scan_and_read_accept_and_reject_exactly_the_same_files(name: str) -> None:
    data, expected = CASES[name]
    assert outcome(scan_summary_csv, data) == expected
    assert outcome(read_summary_csv, data) == expected


def test_a_malformed_second_row_is_caught() -> None:
    lines = csv().split(b"\r\n")
    lines[1] = lines[1].replace(b"28/02/2025", b"30/02/2025")
    assert outcome(read_summary_csv, b"\r\n".join(lines)) == "rejected:bad_date"


def test_an_error_never_holds_an_identifier_or_content() -> None:
    with pytest.raises(InvalidInputError) as caught:
        read_summary_csv(edit(csv(), "31/01/2025", "31/13/2025"))
    text = caught.value.message + repr(caught.value.details)
    assert SYNTHETIC_NMI11 not in text and SYNTHETIC_SERIAL not in text and "31/13/2025" not in text
